param()
$ErrorActionPreference='Stop'
Add-Type -AssemblyName PresentationCore,PresentationFramework,WindowsBase
$pageRoot=Split-Path -Parent $PSScriptRoot
function Read-PageImage([string]$path){$stream=[IO.File]::OpenRead((Join-Path $pageRoot $path));try{$image=[Windows.Media.Imaging.BitmapImage]::new();$image.BeginInit();$image.CacheOption='OnLoad';$image.StreamSource=$stream;$image.EndInit();$image.Freeze();return $image}finally{$stream.Dispose()}}
function Label-Page($dc,[string]$text,[double]$x,[double]$y){$label=[Windows.Media.FormattedText]::new($text,[Globalization.CultureInfo]::GetCultureInfo('zh-CN'),[Windows.FlowDirection]::LeftToRight,[Windows.Media.Typeface]::new('Microsoft YaHei UI'),16,[Windows.Media.Brushes]::Black,1.0);$dc.DrawText($label,[Windows.Point]::new($x,$y))}
function Save-PageVisual($visual,[int]$width,[int]$height,[string]$name){$bitmap=[Windows.Media.Imaging.RenderTargetBitmap]::new($width,$height,96,96,[Windows.Media.PixelFormats]::Pbgra32);$bitmap.Render($visual);$encoder=[Windows.Media.Imaging.PngBitmapEncoder]::new();$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bitmap));$stream=[IO.File]::Create((Join-Path $pageRoot ('artifacts/page-lab/'+$name)));try{$encoder.Save($stream)}finally{$stream.Dispose()}}
$report=Get-Content -LiteralPath (Join-Path $pageRoot 'artifacts/page-lab/release-verification/page-test-results.json') -Raw -Encoding UTF8|ConvertFrom-Json
$scale=.68/($report.dpi/96.0)
$v=[Windows.Media.DrawingVisual]::new();$dc=$v.RenderOpen();$dc.DrawRectangle([Windows.Media.Brushes]::White,$null,[Windows.Rect]::new(0,0,1960,720));$x=24
foreach($item in @(@('01-home','首页'),@('02-ordinary-editor','普通提醒编辑'),@('09-medicine-editor','药物计划编辑'))){$image=Read-PageImage ('artifacts/page-lab/release-verification/'+$item[0]+'.png');Label-Page $dc $item[1] $x 16;$dc.DrawImage($image,[Windows.Rect]::new($x,52,$image.PixelWidth*$scale,$image.PixelHeight*$scale));$x+=$image.PixelWidth*$scale+24}
Label-Page $dc '真实原生页面，按同一 DPI 比例缩放；此图供页面评审，不代表正式产品已经替换。' 24 680;$dc.Close();Save-PageVisual $v 1960 720 '01-three-baseline-pages.png'
$v=[Windows.Media.DrawingVisual]::new();$dc=$v.RenderOpen();$dc.DrawRectangle([Windows.Media.Brushes]::White,$null,[Windows.Rect]::new(0,0,1880,770));$x=24
foreach($item in @(@('03-ordinary-errors','普通字段错误'),@('10-medicine-errors','药物时刻错误'),@('17-compact-medicine','紧凑窗口与固定操作区'))){$image=Read-PageImage ('artifacts/page-lab/release-verification/'+$item[0]+'.png');$fit=[Math]::Min(580.0/$image.PixelWidth,640.0/$image.PixelHeight);Label-Page $dc $item[1] $x 16;$dc.DrawImage($image,[Windows.Rect]::new($x,52,$image.PixelWidth*$fit,$image.PixelHeight*$fit));$x+=620};$dc.Close();Save-PageVisual $v 1880 770 '02-errors-and-compact.png'
$reference=Read-PageImage 'design/ui/轻透主题/01-暖香槟-默认.png';$reference=[Windows.Media.Imaging.CroppedBitmap]::new($reference,[Windows.Int32Rect]::new(52,122,1004,820));$actual=Read-PageImage 'artifacts/page-lab/release-verification/01-home.png'
$v=[Windows.Media.DrawingVisual]::new();$dc=$v.RenderOpen();$dc.DrawRectangle([Windows.Media.Brushes]::White,$null,[Windows.Rect]::new(0,0,2072,930));Label-Page $dc '已选效果图' 24 16;Label-Page $dc '原生基准首页，包含独立样板标识' 1060 16;$dc.DrawImage($reference,[Windows.Rect]::new(24,56,1004,820));$dc.DrawImage($actual,[Windows.Rect]::new(1060,56,1004,1004*$actual.PixelHeight/$actual.PixelWidth));Label-Page $dc '按宽度归一并保留比例。窗口比例和样板标识不同，材质光学差异继续保留。' 24 895;$dc.Close();Save-PageVisual $v 2072 930 '03-reference-home-comparison.png'
Write-Output 'Three baseline pages, state sheet and source comparison rendered.'
